  "steps": [
    {
      "name": "Start",
      "entry": "Pallet arrives in test position (ZS-2008 rising edge), auto mode, no ST20 fault, idle",
      "exit": "Clamp sequence initiated"
    },
    {
      "name": "Clamp",
      "entry": "Start sequence initiated",
      "exit": "Clamp confirmed closed (ZS-2002A made and ZS-2002B clear)"
    },
    {
      "name": "Fill",
      "entry": "Clamp confirmed closed",
      "exit": "PT-2001 reaches 14.50 kPa"
    },
    {
      "name": "Stabilise",
      "entry": "Fill complete",
      "exit": "Settling time elapsed"
    },
    {
      "name": "Test",
      "entry": "Stabilisation complete",
      "exit": "10.0 s test window elapsed"
    },
    {
      "name": "Decision",
      "entry": "Test window complete",
      "exit": "Pass or fail result generated based on decay calculation"
    },
    {
      "name": "Vent and unclamp",
      "entry": "Decision complete or fault abort",
      "exit": "Vent time elapsed, PT-2001 below 1.00 kPa, pressure signal healthy, and clamp confirmed open"
    },
    {
      "name": "Done",
      "entry": "Clamp confirmed open",
      "exit": "Pallet leaves"
    }
  ],
  "interlocks": [
    {
      "cause": "Clamp confirmation lost (ZS-2002A not made or ZS-2002B not clear)",
      "effect": "Fill valve closes immediately"
    },
    {
      "cause": "PT-2001 signal below -5.00 kPa (wire break)",
      "effect": "Cycle start inhibited and unclamp held"
    },
    {
      "cause": "E-stop chain lost during a cycle",
      "effect": "Cycle aborts to VENT with a FAIL result"
    },
    {
      "cause": "Over-pressure (PT-2001 above 20.00 kPa)",
      "effect": "Fill valve closed, vent valve held open, cycle aborted with a FAIL result"
    }
  ],
  "alarms": [
    {
      "name": "Fill timeout",
      "condition": "Test pressure not reached within 8.0 s",
      "action": "Abort to VENT, FAIL"
    },
    {
      "name": "Over-pressure",
      "condition": "PT-2001 above 20.00 kPa",
      "action": "Latched, fill closed, vent held open, FAIL"
    },
    {
      "name": "PT-2001 signal fault",
      "condition": "Reading below -5.00 kPa (wire break)",
      "action": "Cycle start inhibited; unclamp held"
    },
    {
      "name": "Supply air low",
      "condition": "PS-2009 lost while busy",
      "action": "Latched, abort to VENT, FAIL"
    }
  ],
